SELECT status, CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END AS shipped_cohort, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(carrier))) AS carrier_values, SUM(CASE WHEN status = 'RETURNED' THEN cost ELSE 0 END) AS returned_cost FROM shipments WHERE carrier IN ('UPS', 'FedEx') AND (carrier IS NULL OR order_id IN (1, 4, 9, 21)) GROUP BY status, shipped_cohort;
